using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval: returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded: {probed!.Type.Name}");
}

// Demonstrate the "not available" path using a source-gen-only options instance
// that has no resolver for the target type.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// DefaultJsonTypeInfoResolver resolves everything, so swap in an empty resolver:
limited.TypeInfoResolver = JsonTypeInfoResolver.Combine(); // resolves nothing

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine("Unexpectedly found metadata!");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) on limited options: not available (no exception thrown)");
}

record Person(string Name, int Age);

